// slide-01.js - Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Cloudflare Radar 2024 Year in Review'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();

  // Dark navy background
  slide.background = { color: theme.primary };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Left decorative element - vertical bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.8, w: 0.06, h: 2.2,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Cloudflare Radar", {
    x: 0.9, y: 1.7, w: 8, h: 0.8,
    fontSize: 44, fontFace: "Arial",
    color: theme.light, bold: true,
    margin: 0
  });

  slide.addText("2024 Year in Review", {
    x: 0.9, y: 2.4, w: 8, h: 0.9,
    fontSize: 56, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    margin: 0
  });

  // Subtitle description
  slide.addText("Global Internet traffic patterns, adoption trends,\nconnectivity disruptions, and security insights", {
    x: 0.9, y: 3.5, w: 7, h: 0.8,
    fontSize: 16, fontFace: "Arial",
    color: theme.light, bold: false,
    margin: 0
  });

  // Bottom decorative bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325,
    fill: { color: theme.secondary }
  });

  // Source text
  slide.addText("Source: Cloudflare Radar 2024 Year in Review", {
    x: 0.5, y: 5.35, w: 5, h: 0.25,
    fontSize: 10, fontFace: "Arial",
    color: theme.light, bold: false,
    margin: 0
  });

  // Cloudflare logo text
  slide.addText("CLOUDFLARE", {
    x: 8.5, y: 5.35, w: 1.2, h: 0.25,
    fontSize: 10, fontFace: "Arial",
    color: theme.accent, bold: true,
    align: "right", margin: 0
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

