    color: "FFFFFF", bold: true,
    margin: 0
  });

  // Left side - Top 10 table
  const services = [
    { rank: "#1", service: "Google" },
    { rank: "#2", service: "Facebook" },
    { rank: "#3", service: "Apple" },
    { rank: "#4", service: "TikTok" },
    { rank: "#5", service: "AWS" },
    { rank: "#6", service: "Microsoft" },
    { rank: "#7", service: "Instagram" },
    { rank: "#8", service: "YouTube" },
    { rank: "#9", service: "Amazon" },
    { rank: "#10", service: "WhatsApp" }
  ];

  // Table background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 4.8, h: 3.0,
    fill: { color: "FFFFFF" },
    line: { color: theme.light, width: 0.5 }
  });

  // Table header
