    x: 5.5, y: 3.85, w: 4.0, h: 1.4,
    fill: { color: theme.primary }
  });

  slide.addText("Generative AI", {
    x: 5.7, y: 4.0, w: 3.6, h: 0.35,
    fontSize: 16, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    margin: 0
