// slide-05.js - Internet Disruptions
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: '225 Major Disruptions: Government Shutdowns Lead Outage Causes'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.primary }
  });

  slide.addText("225 Major Disruptions: Government Shutdowns Lead Outage Causes", {
    x: 0.5, y: 0.2, w: 9, h: 0.5,
    fontSize: 20, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    margin: 0
  });

  // Left side - disruption causes bar chart visualization
  const disruptions = [
    { cause: "Government Directed", count: 116, color: theme.primary },
    { cause: "Cable Cut", count: 41, color: theme.secondary },
    { cause: "Unknown", count: 16, color: theme.accent },
    { cause: "Power Outage", count: 16, color: theme.accent },
    { cause: "Technical Problem", count: 9, color: theme.light },
    { cause: "Military Action", count: 9, color: theme.light },
    { cause: "Weather", count: 8, color: theme.light },
    { cause: "Maintenance", count: 4, color: theme.light },
    { cause: "Cyber Attack", count: 4, color: theme.light },
    { cause: "Natural Disaster", count: 1, color: theme.light },
    { cause: "Fire", count: 1, color: theme.light }
  ];

  const maxCount = 116;
  const barStartX = 0.5;
  const barWidth = 4.5;
  const barHeight = 0.22;
  let yPos = 1.1;

  disruptions.forEach((item, idx) => {
    const barFillWidth = (item.count / maxCount) * barWidth;

    // Background bar track
    slide.addShape(pres.shapes.RECTANGLE, {
      x: barStartX, y: yPos, w: barWidth, h: barHeight,
      fill: { color: "FFFFFF" },
      line: { color: theme.light, width: 0.5 }
    });

    // Filled bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: barStartX, y: yPos, w: barFillWidth, h: barHeight,
      fill: { color: item.color }
    });

    // Count label
    slide.addText(String(item.count), {
      x: barStartX + barFillWidth + 0.1, y: yPos, w: 0.5, h: barHeight,
      fontSize: 9, fontFace: "Arial",
      color: theme.primary, bold: true,
      valign: "middle",
      margin: 0
    });

    // Cause label
    slide.addText(item.cause, {
      x: barStartX + 0.05, y: yPos, w: 1.8, h: barHeight,
      fontSize: 8, fontFace: "Arial",
      color: idx < 2 ? "FFFFFF" : theme.primary, bold: false,
      valign: "middle",
      margin: 0
    });

    yPos += barHeight + 0.04;
  });

  // Total count highlight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.95, w: 4.5, h: 0.5,
    fill: { color: theme.primary }
  });

  slide.addText("225", {
    x: 0.5, y: 4.95, w: 1.0, h: 0.5,
    fontSize: 28, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle",
    margin: 0
  });

  slide.addText("Major Internet Disruptions Observed in 2024", {
    x: 1.5, y: 4.95, w: 3.3, h: 0.5,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    valign: "middle",
    margin: 0
  });

  // Right side - image and key insight
  slide.addImage({
    path: "imgs/internet-disruption-causes.jpg",
    x: 5.2, y: 1.1, w: 4.3, h: 2.5,
    sizing: { type: 'cover', w: 4.3, h: 2.5 }
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 3.75, w: 4.3, h: 1.7,
    fill: { color: theme.primary }
  });

  slide.addText("Leading Cause: Government-Directed Shutdowns", {
    x: 5.4, y: 3.9, w: 3.9, h: 0.4,
    fontSize: 13, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    margin: 0
  });

  slide.addText("116+ incidents driven by various factors including political unrest, censorship requirements, and national security concerns.", {
    x: 5.4, y: 4.35, w: 3.9, h: 0.6,
    fontSize: 10, fontFace: "Arial",
    color: theme.light, bold: false,
    margin: 0
  });

  slide.addText("Cable cuts (41) and power outages (16) follow as second and third leading causes.", {
    x: 5.4, y: 4.95, w: 3.9, h: 0.4,
    fontSize: 10, fontFace: "Arial",
    color: theme.light, bold: false,
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

