    x: 0.5, y: 4.3, w: 9.0, h: 0.7,
    fill: { color: theme.primary }
  });

  slide.addText("RPKI Valid Routes", {
    x: 0.7, y: 4.35, w: 2.5, h: 0.6,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    valign: "middle",
    margin: 0
  });

  slide.addText("+6.4%", {
    x: 2.8, y: 4.35, w: 1.2, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.accent, bold: true,
    valign: "middle",
    margin: 0
  });

  slide.addText("An important step toward improved Internet routing security", {
