    x: 0.5, y: 1.0, w: 2.5, h: 0.04,
    fill: { color: theme.accent }
  });

  // Five takeaways as cards
  const takeaways = [
    {
      num: "01",
      title: "Traffic Growth Trajectory",
      desc: "17% YoY growth continues; Starlink's 3.3x surge demonstrates satellite connectivity expansion to underserved regions"
    },
    {
      num: "02",
      title: "Post-Quantum Encryption Momentum",
      desc: "From ~2% to 13% of TLS 1.3 traffic following Chrome 124 default enablement — expect continued acceleration"
    },
