// compile.js - Compile all slides into final presentation
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = 'Cloudflare Radar 2024 Year in Review';
pres.author = 'Cloudflare';

// Cloudflare-inspired dark navy theme
const theme = {
  primary: "22223b",    // dark navy - titles, headers
  secondary: "4a4e69",  // secondary dark - body text, accents
  accent: "9a8c98",     // muted purple accent
  light: "c9ada7",      // light rose accent
  bg: "f2e9e4"          // cream background
};

// Load and create all slides
for (let i = 1; i <= 7; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

// Write final presentation
pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => {
    console.log('Presentation created successfully: ./output/final_deck.pptx');
  })
  .catch(err => {
    console.error('Error creating presentation:', err);
  });

